// Sub-Agent: AI Doctor — пакет для агента + ПОЛ красных флагов + мягкая сеть + картотека Meds (Батч 4, Гр.1/6c).
// v4: +medications (лист Meds) для проверки взаимодействий; sheetData читаем по имени ноды (в цепочке теперь Get Meds).
// v3 отличия от v2:
//  - +7 красных флагов: конский хвост (критично при грыже L5/S1), ТЭЛА/ТГВ, суицидальные мысли,
//    атипичный/немой ОКС, ранняя анафилаксия, задержка мочи, острая закрытоугольная глаукома.
//  - red_flag.category: 'emergency' (скорая 103/112) | 'crisis' (суицид — линия помощи, тёплый тон).
//  - soft_flags: односложные «зацепки» (боль в груди / головная боль / онемение / кровь …) НЕ дают
//    короткого замыкания — они уходят в промпт агента как обязательные уточняющие вопросы.
//  - разбор типа входящего: голосовое / пересланное / фото без подписи / документ.
// ВАЖНО: в JS-regex \w НЕ матчит кириллицу. Хелпер rx() подменяет плейсхолдер \W → [а-яёa-z0-9].
const sheetData = (() => { try { return $('User Profile').first().json; } catch (e) { return $input.first().json; } })();
const triggerData = $('Главврач').first().json;
const binaryData = $('Главврач').first().binary;
const m = triggerData.message || {};

// ---------- тип входящего сообщения ----------
const rawText = m.caption || m.text || '';
const isForwarded = !!(m.forward_origin || m.forward_from || m.forward_from_chat || m.forward_sender_name || m.forward_date);
let msg;
if (rawText) {
  msg = (isForwarded ? '[Пересланное пациентом сообщение] ' : '') + rawText;
} else if (m.voice || m.audio || m.video_note) {
  msg = '[Пациент прислал голосовое/аудио. Автоматической расшифровки нет. Ответь по тому, что известно из карты и истории, и попроси продублировать жалобу текстом.]';
} else if (m.photo) {
  msg = '[Пациент прислал фото без подписи. Опиши, что видно, и спроси, что именно беспокоит.]';
} else if (m.document) {
  msg = '[Пациент прислал файл: ' + (m.document.file_name || 'без имени') + '. Если это медицинский документ — попроси прислать через регистратора или текстом ключевые цифры.]';
} else {
  msg = 'Посмотри на это.';
}

// ---------- хелпер паттернов ----------
const L = '[а-яёa-z0-9]';
const rx = (s) => new RegExp(s.replace(/\\W/g, L), 'i');

// ======================= ЖЁСТКИЕ КРАСНЫЕ ФЛАГИ =======================
// category: 'emergency' по умолчанию; 'crisis' переопределяется ниже для суицидальных мыслей.
const RED_FLAGS = [
  ['боль в груди с иррадиацией / одышка',
    rx('(груд|за\\s*грудин)[^.!?]{0,70}(отда[еёт]|иррадиир|в\\s*(лев\\W*\\s*)?руку|в\\s*(нижн\\W*\\s*)?челюст|в\\s*лопатк|в\\s*шею)|дав(ит|ящ\\W*|ление)[^.!?]{0,45}груд[^.!?]{0,45}(одышк|воздух|пот\\W|тошнот|слабост)|жж[её]т?[^.!?]{0,25}груд[^.!?]{0,45}(одышк|рук|челюст|пот)')],
  ['атипичный / немой ОКС (дискомфорт в груди или эпигастрии + вегетатика)',
    rx('(дискомфорт|тяжест\\W*|давит|сдавл\\W*|жж[её]т|жжени\\W*|ноет|поджимает)[^.!?]{0,30}(в\\s*груди|за\\s*грудин|в\\s*грудн|под\\s*ложечк|в\\s*верху\\s*живот|в\\s*эпигастр|солнечн\\W*\\s*сплетени)[^.!?]{0,70}(холодн\\W*\\s*пот|облив\\W*\\s*потом|тошнот|подташнива|резк\\W*\\s*слабост|дурнот|одышк|нехватк\\W*\\s*воздух|страх\\s*смерти|отдает\\s*в\\s*(челюст|спину|обе\\s*руки))|(за\\s*грудин|в\\s*груди|в\\s*грудн|под\\s*ложечк|в\\s*эпигастр)[^.!?]{0,25}(жж[её]|печ[её]т|дав|тяж|сжима|поджим|дискомфорт|ноет)[^.!?]{0,70}(холодн\\W*\\s*пот|облив\\W*\\s*потом|тошнот|подташнива|резк\\W*\\s*слабост|дурнот|одышк|нехватк\\W*\\s*воздух|страх\\s*смерти|отдает\\s*в\\s*(челюст|спину|обе\\s*руки))|(ноет|сжимает|тянет|давит)[^.!?]{0,20}(челюст|обе\\s*руки)[^.!?]{0,45}(при\\s*ходьбе|при\\s*нагрузк|холодн\\W*\\s*пот|одышк)')],
  ['признаки инсульта',
    rx('(онемел\\W*|отнял\\W*|отня\\W*|перестал\\W*\\s*(слушать|двигать|шевелить|работать))[^.!?]{0,45}(рук|ног|половин\\W*\\s*тела|лиц)|перекос\\W*[^.!?]{0,20}(лиц|рот)|(речь|говор\\W*)[^.!?]{0,25}(спутан|невнятн|заплет|пропал)|(резко|внезапно)[^.!?]{0,25}не\\s*могу\\s*(говорить|двигать)|двоится\\s*в\\s*глаз|(внезапн\\W*|резк\\W*)[^.!?]{0,25}(слепот|потер\\W*\\s*зрени)')],
  ['конский хвост (седловидная анестезия / тазовые органы + спина-нога)',
    rx('онем\\W*[^.!?]{0,45}(промежност|седл\\W*|межягодич|внутренн\\W*\\s*(поверхност|сторон)\\W*\\s*(бедер|б[её]дер)|паху\\b|в\\s*паху|половых\\s*орган|мошонк|анус|заднего\\s*прохода)|(не\\s*чувству\\W*|онем\\W*|потер\\W*\\s*чувствит\\W*)[^.!?]{0,45}(когда\\s*(мочусь|писаю|хожу\\s*в\\s*туалет)|при\\s*мочеиспуск|позыв\\W*\\s*в\\s*туалет|прямой\\s*кишк|дефекац)|(недержан\\W*|перестал\\W*\\s*(контролир|держать|чувствовать)|не\\s*контролир\\W*|непроизвольн\\W*|не\\s*удерж\\W*)[^.!?]{0,40}(моч\\W*|кал\\b|стул|кишечник|туалет|мочеиспуск)[^.!?]{0,70}(спин|поясниц|грыж|ног|радикул|прострел)|(обе\\s*ног|две\\s*ног|ноги\\s*обе)[^.!?]{0,30}(отнима\\W*|неме\\W*|отказыва\\W*|подкашива\\W*|ватн\\W*|слабост)[^.!?]{0,45}(спин|поясниц|грыж|радикул)')],
  ['ТЭЛА / ТГВ (внезапная одышка + плевральная боль / отёк одной ноги / кровохарканье)',
    rx('(внезапн\\W*|резк\\W*|вдруг|ни\\s*с\\s*того)[^.!?]{0,25}(одышк|трудно\\s*дышать|не\\s*хватает\\s*воздух|задыха\\W*|нехватк\\W*\\s*воздух)[^.!?]{0,75}(боль[^.!?]{0,15}в\\s*груди|при\\s*вдохе|колет\\s*при\\s*вдохе|кашл\\W*[^.!?]{0,15}кров|нога\\s*отекл|икр\\W*[^.!?]{0,15}(боли|отекл|распухл|горяч))|(одна\\s*нога|левая\\s*голень|правая\\s*голень|икра|голень)[^.!?]{0,30}(отекл|распухл|горяч\\W*|покраснел\\W*|тверд\\W*\\s*и\\s*боли)[^.!?]{0,55}(одышк|груд|дышать|при\\s*вдохе)|кашл\\W*[^.!?]{0,20}(с\\s*кровью|кровь\\W)[^.!?]{0,50}(одышк|боль[^.!?]{0,15}в\\s*груди|дышать)')],
  ['суицидальные мысли',
    rx('(не\\s*хочу\\s*(больше\\s*)?жить|нет\\s*смысла\\s*(жить|дальше)|не\\s*вижу\\s*смысла\\s*жить|жить\\s*(больше\\s*)?не\\s*хочу|покончить\\s*с\\s*собой|покончу\\s*с\\s*собой|свести\\s*счеты\\s*с\\s*жизнью|лучше\\s*(бы\\s*)?(мне\\s*)?не\\s*просыпаться|мысли\\s*о\\s*суицид|суицидальн\\W*\\s*мысл|думаю\\s*о\\s*том\\s*чтобы\\s*(покончить|уйти\\s*из\\s*жизни)|уйти\\s*из\\s*жизни|убить\\s*себя|причинить\\s*себе\\s*вред|незачем\\s*(больше\\s*)?жить|не\\s*хочу\\s*просыпаться\\s*по\\s*утрам)')],
  ['громоподобная / worst-ever головная боль',
    rx('(сам\\W*\\s*(сильн\\W*|жутк\\W*|невыносим\\W*|ужасн\\W*)[^.!?]{0,25}(головн\\W*\\s*боль|голова))|громоподобн\\W*[^.!?]{0,20}голов|(внезапн\\W*|резк\\W*)[^.!?]{0,25}(сильнейш\\W*|нестерпим\\W*|как\\s*удар)[^.!?]{0,20}голов|голов\\W*\\s*боль[^.!?]{0,35}(в\\s*жизни|никогда\\s*так|как\\s*удар|громоподоб)|(сильнейш|нестерпим)\\W*\\s*(головн\\W*\\s*боль|голов)')],
  ['ЖКТ-кровотечение',
    rx('кофейн\\W*\\s*гущ|рвот\\W*[^.!?]{0,25}(кровь|с\\s*кровью|бур\\W|ч[ёе]рн)|рв[ае]т[^.!?]{0,20}(кровь|кофейн)|ч[ёе]рн\\W*[^.!?]{0,25}(стул|кал\\b)(?![^.!?]{0,20}(активирован|уголь|железо|висмут|черник|св[её]кл))|(стул|кал)\\W*[^.!?]{0,20}(ч[ёе]рн|как\\s*д[её]готь|д[её]гтеобразн|смолист)|д[её]гтеобразн\\W*\\s*(стул|кал)|мелена|(кровь|ал\\W*\\s*кров)[^.!?]{0,25}(в\\s*стуле|в\\s*кале|из\\s*(зад|прям\\W*\\s*кишк)|при\\s*дефекац|обильн)')],
  ['отёк гортани / удушье / ранняя анафилаксия',
    rx('от[ёек]\\W*[^.!?]{0,20}(гортан|язык\\W|горл|губ)|(трудно|тяжело|не\\s*могу|стало\\s*трудно)\\s*(дышать|глотать|вдохнуть|сделать\\s*вдох)|горло\\s*(сжим|перекр|отекл|распух|сдавл)|распух\\W*[^.!?]{0,15}(лицо|горло|язык|губ)|крапивниц\\W*[^.!?]{0,25}(вс[её]\\s*тело|от[её]к|дыхан|горло)|(съел|поел|выпил|принял|укол\\W*|укус\\W*|ужалил\\W*|оса\\W*|пчел\\W*)[^.!?]{0,60}(крапивниц|сыпь\\s*по\\s*всему\\s*тел|чешется\\s*вс[её]\\s*тел|вс[её]\\s*тело\\s*в\\s*пятн|отек\\W*\\s*лиц)[^.!?]{0,70}(горло|глота|дыш|голос\\s*сел|тошнот|рвот|живот\\s*скрут|кружит|давлени\\W*\\s*упал|слабост)')],
  ['потеря сознания / судороги',
    rx('потер\\W*\\s*сознани|(упал|потерял\\W*|отключил\\W*)[^.!?]{0,20}(в\\s*обморок|сознание|отруб)|(перв\\W*\\s*раз|впервые)[^.!?]{0,20}судорог|судорог\\W*[^.!?]{0,25}(не\\s*прекращ|вс[её]\\s*тело|минут)|эпи?приступ|припадок\\s*(с|со|без)\\s*судорог')],
  ['внезапная нестерпимая боль в животе/боку/спине',
    rx('(внезапн\\W*|резк\\W*|остр\\W*)[^.!?]{0,15}(сильнейш\\W*|нестерпим\\W*|острейш\\W*|кинжальн\\W*|невыносим\\W*)[^.!?]{0,20}бол\\W*[^.!?]{0,20}(живот|поясниц|спин|бок|подреберь)|бол\\W*[^.!?]{0,12}(как\\s*удар\\s*ножом|будто\\s*разрыв)')],
  ['задержка мочи',
    rx('(не\\s*могу\\s*(по)?мочит\\W*|не\\s*могу\\s*сходить\\s*по-?маленьк\\W*|моча\\s*не\\s*идет|не\\s*идет\\s*моча|мочев\\W*\\s*переполн|переполнен\\s*мочев|распира\\W*\\s*внизу\\s*живот|не\\s*могу\\s*опорожнить\\s*мочев)[^.!?]{0,55}(боль|распира|переполн|полдня|сутки|давно|много\\s*часов|тужусь|не\\s*получается)')],
  ['острая закрытоугольная глаукома / внезапная потеря зрения на один глаз',
    rx('(резк\\W*|сильн\\W*|остр\\W*)[^.!?]{0,15}бол\\W*[^.!?]{0,15}(в\\s*глаз|глаза)[^.!?]{0,70}(радужн\\W*\\s*круг|ореол\\W*\\s*вокруг\\s*свет|круги\\s*вокруг\\s*ламп|затуман\\W*\\s*зрени|глаз\\s*(красн|твердый|каменн|как\\s*камень)|тошнот|рвот|половин\\W*\\s*голов)|(внезапн\\W*|резк\\W*|за\\s*час|за\\s*(несколько\\s*)?минут)[^.!?]{0,20}(упало|пропало|исчезло|потемнело|потерял\\W*)\\s*зрени[^.!?]{0,25}(на\\s*один\\s*глаз|в\\s*одном\\s*глаз|левым\\s*глаз|правым\\s*глаз|один\\s*глаз)')],
  ['лихорадка + спутанность / ригидность шеи',
    rx('(температур\\W*|жар|лихорадк)[^.!?]{0,20}(3[89]|4[012])[^.!?]{0,55}(спутан|брежу|бред\\b|не\\s*могу\\s*согнуть\\s*шею|ригидн|светобоязн|сыпь\\s*не\\s*исчез)|не\\s*могу\\s*согнуть\\s*шею[^.!?]{0,25}(температур|жар|свет|голов)')],
];

const redFlag = { hit: false, matched: [], category: 'emergency' };
for (const [label, re] of RED_FLAGS) {
  if (re.test(msg)) { redFlag.hit = true; redFlag.matched.push(label); }
}
if (redFlag.hit && redFlag.matched.length === 1 && /суицидальные/.test(redFlag.matched[0])) {
  redFlag.category = 'crisis';
} else if (redFlag.matched.some(x => /суицидальные/.test(x))) {
  // суицид + что-то ещё → всё равно ведём как emergency, но пометим
  redFlag.category = 'emergency';
}

// ======================= МЯГКАЯ СЕТЬ (не короткое замыкание) =======================
// Односложная зацепка → агент ОБЯЗАН уточнить перечисленное прежде чем строить гипотезы.
const SOFT = [
  [rx('(боль[^.!?]{0,12}в\\s*груди|груд\\W*\\s*болит|болит[^.!?]{0,12}груд|за\\s*грудин|колет\\s*в\\s*сердц|давит\\s*в\\s*груди)'),
   'Боль/дискомфорт в груди: иррадиация (рука/челюсть/лопатка/спина/эпигастрий), одышка, холодный пот, тошнота, связь с физнагрузкой, длительность эпизода, было ли такое раньше и что снимало.'],
  [rx('(головн\\W*\\s*боль|болит\\s*голова|голова\\s*болит|мигрен)'),
   'Головная боль: внезапная («секунды-минуты, как удар») или постепенная; самая сильная в жизни?; температура, ригидность шеи, свето/звукобоязнь, сыпь; онемение/слабость/нарушение речи/двоение; травма головы в последние дни.'],
  [rx('(онемел|онемени\\W*|неме\\W*т|отня\\W*|отнимает|покалыван|мурашк|ватн\\W*\\s*ног)'),
   'Онемение/слабость: одна сторона или обе; лицо, речь, рука (инсульт); промежность/седловидная зона + контроль мочеиспускания и стула (конский хвост — критично при грыже L5/S1); нарастает или стабильно; с какого момента.'],
  [rx('(кровь|кров\\W*\\s*т|кровот\\W*|окровав|кровит)'),
   'Кровь: точный источник (рвота / стул / моча / мокрота / нос / дёсны / рана); цвет (алая / тёмная / «кофейная гуща» / чёрный дёгтеобразный); объём; однократно или повторяется; принимает ли антикоагулянты/НПВС.'],
  [rx('(температур|жар\\b|лихорад|озноб|знобит)'),
   'Лихорадка: точная цифра и сколько дней; ригидность затылка, спутанность, сыпь которая не бледнеет при надавливании; одышка; локальная боль (живот/бок/горло/ухо/мочеиспускание); поездки, укусы клещей.'],
  [rx('(задыха\\W*|одышк|не\\s*хватает\\s*воздух|тяжело\\s*дышать|трудно\\s*дышать|нехватк\\W*\\s*воздух)'),
   'Одышка: в покое или при нагрузке; появилась внезапно или постепенно; боль в груди при вдохе; отёк или боль в одной ноге (ТГВ); кашель, кровь в мокроте; тяжело дышать лёжа (ортопноэ); отёки ног к вечеру.'],
  [rx('(сильно\\s*похуд|похудел\\W*\\s*без\\s*причин|теряю\\s*вес|резко\\s*похуд|сброс\\W*\\s*вес\\W*\\s*без)'),
   'Потеря веса: сколько кг за какой срок; аппетит; ночная потливость; субфебрилитет; изменения стула/глотания; когда последний раз проходил онко-скрининги по возрасту.'],
  [rx('(родинк|невус|пятно\\s*на\\s*коже|нарост|новообразован|уплотнени\\W*\\s*в\\s*(груд|молочн)|шишк\\W*\\s*(под\\s*кож|в\\s*груд|на\\s*шее))'),
