    const lastIndex = stack.lastIndexOf(tag);
    if (lastIndex !== -1) {
      stack.splice(lastIndex, 1); 
    }
  }
}

// Все теги, которые остались в "памяти" - нейросеть забыла закрыть!
// Аккуратно закрываем их в самом конце текста в обратном порядке
for (let i = stack.length - 1; i >= 0; i--) {
  text += `</${stack[i]}>`;
}

// 6. Убираем лишние пустые строки
text = text.replace(/\n{3,}/g, '\n\n');

return { 
  json: { 
    ...$json,
    output: text.trim() 
  } 
};

// Разбор JSON-конверта от агента. Записи (симптом/заметка/расследование/анализы) — НЕ
// инструменты агента, он кладёт их в JSON, n8n пишет нодами ниже. Здесь же — ремонт
// типовой поломки Gemini (незаэкранированная " внутри answer) и защита от «утёкшего» вызова.
let raw = String($json.output || '').trim();
raw = raw.replace(/^﻿/, '').replace(/^\s*[\x60]{3}(?:json)?\s*/i, '').replace(/\s*[\x60]{3}\s*$/, '').trim();

let env = null;
try { env = JSON.parse(raw); } catch (e) {}

// --- РЕМОНТ: конверт явно начат ("{ ... "answer": " ...), но JSON.parse упал ---
// Самая частая причина у gemini-3.8-flash: голая " внутри текста answer (напр. Прикрыть "дышащей" повязкой).
if ((!env || typeof env !== 'object' || Array.isArray(env)) && /^\s*\{[\s\S]{0,400}?"answer"\s*:\s*"/.test(raw)) {
  try {
    const keyIdx = raw.search(/"answer"\s*:/);
    const vs = raw.indexOf('"', raw.indexOf(':', keyIdx)) + 1;
    const endRe = /"\s*,\s*\r?\n?\s*"(?:awaiting_reply|log_symptom|medical_note|investigation|lab_plan)"\s*:/g;
    endRe.lastIndex = vs;
    const em = endRe.exec(raw);
    const ve = em ? em.index : raw.length;
    const inner = raw.slice(vs, ve);
    // раскодируем те экранизации, что модель ВСЁ ЖЕ поставила — получаем чистый текст
    const plain = inner
      .replace(/\r\n?/g, '\n')
      .replace(/\\r\\n?/g, '\n').replace(/\\n/g, '\n').replace(/\\t/g, '\t')
      .replace(/\\"/g, '"').replace(/\\\\/g, '\\')
      .trim();
    // пересобираем весь конверт с правильно закодированным answer
    const rebuilt = raw.slice(0, keyIdx) + '"answer": ' + JSON.stringify(plain) + (em ? raw.slice(em.index + 1) : '\n}');
    try { env = JSON.parse(rebuilt); } catch (e2) { env = null; }
    if (!env || typeof env !== 'object') env = { answer: plain };
    if (!env.answer) env.answer = plain;
    // добираем поля регэкспом, если пересборка их потеряла
    if (env.awaiting_reply === undefined) {
      const am = raw.match(/"awaiting_reply"\s*:\s*(true|false)/);
      if (am) env.awaiting_reply = am[1] === 'true';
    }
    for (const k of ['log_symptom', 'medical_note', 'investigation']) {
      if (env[k] === undefined) {
        const km = raw.match(new RegExp('"' + k + '"\\s*:\\s*(null|\\{[\\s\\S]*?\\n\\s*\\})'));
        if (km) { if (km[1] === 'null') env[k] = null; else { try { env[k] = JSON.parse(km[1]); } catch (e3) { env[k] = null; } } }
      }
    }
    if (env.lab_plan === undefined) {
      const pm = raw.match(/"lab_plan"\s*:\s*(null|\[[\s\S]*?\]\s*)/);
      if (pm) { if (pm[1].trim() === 'null') env.lab_plan = null; else { try { env.lab_plan = JSON.parse(pm[1]); } catch (e4) { env.lab_plan = null; } } }
    }
  } catch (eR) { /* ремонт не удался — уйдём в общий фолбэк ниже */ }
}

if (!env || typeof env !== 'object' || Array.isArray(env)) {
  // не JSON и не чинится. Утёкший tool-call → ошибка; нормальная проза → оборачиваем.
  const looksLikeLeak = /^\s*(Calling|Invoking|Использую|Вызываю|Вызов)\s+[A-Za-z_А-Яа-яЁё]/i.test(raw)
    || /\bwith\s+input\s*:\s*\{/i.test(raw)
    || /<\|?tool_call\|?>|functions\.[A-Za-z_]+\s*\(/i.test(raw)
    || (raw.startsWith('{') && !/"answer"\s*:/.test(raw) && /"(Symptom_ID|Note|Inv_ID|Plan_ID)"\s*:/.test(raw));
  if (raw && raw.length > 15 && !looksLikeLeak) {
    env = { answer: raw };
  } else {
    throw new Error('Агент не вернул валидный JSON-конверт с полем answer. Начало: ' + raw.slice(0, 160));
  }
}
if (!env.answer || typeof env.answer !== 'string' || env.answer.trim().length < 3) {
  throw new Error('В конверте агента нет поля answer. Ключи: ' + Object.keys(env).join(',') + ' | ' + raw.slice(0, 120));
}

const chat_id = (() => { try { return $('Главврач').first().json.message.chat.id; } catch (e) { return null; } })();
const dtHM = new Date(Date.now() + 10 * 3600e3).toISOString().slice(0, 16).replace('T', ' '); // yyyy-MM-dd HH:mm
const dISO = dtHM.slice(0, 10);
const dDot = dISO.replace(/-/g, '.');
const dtTs = new Date().toISOString(); // UTC для Postgres timestamptz

const awaiting = env.awaiting_reply === true || env.awaiting_reply === 'true';
const ls = (!awaiting && env.log_symptom && typeof env.log_symptom === 'object') ? env.log_symptom : null;
const mn = (!awaiting && env.medical_note) ? (typeof env.medical_note === 'string' ? { Note: env.medical_note } : env.medical_note) : null;
const iv = (!awaiting && env.investigation && typeof env.investigation === 'object') ? env.investigation : null;
const lp = (!awaiting && Array.isArray(env.lab_plan) && env.lab_plan.length) ? env.lab_plan : null;
const invAction = iv ? String(iv.action || 'open').toLowerCase() : '';

return [{
  json: {
    output: env.answer,
    chat_id,
    dt_hm: dtHM, dt_iso: dISO, dt_dot: dDot, dt_ts: dtTs,
    log_symptom: ls, medical_note: mn, investigation: iv, lab_plan: lp,
    has_symptom: !!ls, has_note: !!mn, has_inv: !!iv, has_lab: !!lp,
    inv_action: invAction,
    awaiting_reply: awaiting,
  },
}];

