    + ' \u00b7 \u0430\u043b\u043a\u043e\u0433\u043e\u043b\u044c \u0432\u0447\u0435\u0440\u0430 ' + (_raw['\u0410\u043b\u043a\u043e\u0433\u043e\u043b\u044c_\u0433\u0440'] ?? '0') + '\u0433'
    + (_raw['\u0416\u0430\u043b\u043e\u0431\u044b_\u0432\u0447\u0435\u0440\u0430'] ? ' \u00b7 \u0436\u0430\u043b\u043e\u0431\u044b \u0432\u0447\u0435\u0440\u0430: ' + _raw['\u0416\u0430\u043b\u043e\u0431\u044b_\u0432\u0447\u0435\u0440\u0430'] : ''));
const _notes = (_hc.medical_notes_recent || []).slice(0, 4)
  .map(x => '\u2022 ' + x.date + ' [' + (x.category || '?') + '] ' + String(x.note || '').slice(0, 280)).join('\n') || '\u043d\u0435\u0442 \u043d\u0435\u0434\u0430\u0432\u043d\u0438\u0445 \u0437\u0430\u043f\u0438\u0441\u0435\u0439';
const _adv = _hc.recommendation && _hc.recommendation.text
  ? '(' + (_hc.recommendation.date || '') + ') ' + String(_hc.recommendation.text).slice(0, 380).replace(/\s+/g, ' ')
  : '\u043d\u0435\u0442';

const dossier = [
  '## \ud83d\udccb \u041a\u0410\u0420\u0422\u0410 \u041d\u0410 \u0421\u0415\u0413\u041e\u0414\u041d\u042f \u2014 \u044d\u0442\u0438 \u0434\u0430\u043d\u043d\u044b\u0435 \u0443\u0436\u0435 \u043f\u043e\u0434\u0433\u0440\u0443\u0436\u0435\u043d\u044b. Read_Symptoms / Read_Investigations / Get_Patient_Medical_History \u0432\u044b\u0437\u044b\u0432\u0430\u0439 \u0422\u041e\u041b\u042c\u041a\u041e \u0435\u0441\u043b\u0438 \u043d\u0443\u0436\u043d\u0430 \u0438\u0441\u0442\u043e\u0440\u0438\u044f \u0413\u041b\u0423\u0411\u0416\u0415 \u044d\u0442\u043e\u0439.',
  '',
  '\u0421\u0418\u041c\u041f\u0422\u041e\u041c\u042b (Symptom_Log' + (Object.keys(_symById).length ? ', ' + Object.keys(_symById).length + ' \u0442\u0435\u043c' : ' \u2014 \u043f\u0443\u0441\u0442\u043e') + '):',
  _symLines || '\u0437\u0430\u043f\u0438\u0441\u0435\u0439 \u043d\u0435\u0442',
  '',
  '\u0420\u0410\u0421\u0421\u041b\u0415\u0414\u041e\u0412\u0410\u041d\u0418\u042f (Investigations):',
  _invText,
  '',
  '\u0422\u0420\u0415\u041a\u0415\u0420\u042b Garmin (\u0437\u0430 \u0432\u0447\u0435\u0440\u0430): ' + _trk,
  '\u0422\u0440\u0435\u043d\u0434 \u043d\u0435\u0434\u0435\u043b\u0438: ' + _trendLine + '. \u0410\u043d\u043e\u043c\u0430\u043b\u0438\u0438 \u0434\u043e\u0437\u043e\u0440\u0430: ' + _anom + '.',
  '',
  '\u041f\u0418\u0422\u0410\u041d\u0418\u0415 (\u043a\u043e\u043d\u0442\u0435\u043a\u0441\u0442): ' + _food,
  '',
  '\u041d\u0415\u0414\u0410\u0412\u041d\u0418\u0415 \u0417\u0410\u041f\u0418\u0421\u0418 \u0412 \u041a\u0410\u0420\u0422\u0423 (Doctor_Notes):',
  _notes,
  '',
  '\u0420\u0410\u0417\u0411\u041e\u0420 \u041d\u0415\u0414\u0415\u041b\u0418 (\u0441\u043e\u0432\u0435\u0442\u043d\u0438\u043a): ' + _adv,
].join('\n');
const dossierLoaded = { symptoms: symRows.length > 0, investigations: Array.isArray(invRows), vitals: _pr.hrv != null };

const result = {
  json: {
    dossier,
    dossier_loaded: dossierLoaded,
    medical_record: sheetData,
    user_message: msg,
    telegram_id: m.from && m.from.id,
    chat_id: m.chat && m.chat.id,
    red_flag: redFlag,
    soft_flags,
    soft_probe,
    medications,
    input_kind: rawText ? (isForwarded ? 'forwarded' : 'text')
      : (m.voice || m.audio || m.video_note) ? 'voice'
      : m.photo ? 'photo_no_caption'
      : m.document ? 'document' : 'unknown',
    today: new Date(Date.now() + 10 * 3600 * 1000).toISOString().slice(0, 10),
  },
};
if (binaryData) result.binary = binaryData;
return [result];

let text = $json.output || "";


// 1. Превращаем <br> и <p> в нормальные текстовые переносы
text = text.replace(/<br\s*\/?>/gi, '\n');
text = text.replace(/<\/?p>/gi, '\n\n');

// 2. Спасаем жирный шрифт (Markdown в HTML)
text = text.replace(/\*\*(.*?)\*\*/g, '<b>$1</b>');
text = text.replace(/\*/g, '');

// 3. СПАСАЕМ МЕДИЦИНСКИЕ АНАЛИЗЫ (знаки < и >)
// Если после < идет пробел или цифра - это точно математика, а не тег
text = text.replace(/<(?=\s|[0-9])/g, '&lt;');
// Аналогично для знака >
text = text.replace(/(?<=\s|[0-9])>/g, '&gt;');

// 4. Оставляем только разрешенные теги Телеграма
const allowedTags = "b|strong|i|em|u|s|strike|del|a|code|pre";
const sanitizeRegex = new RegExp(`<\/?(?!(?:${allowedTags})\\b)[a-z0-9]+[^>]*>`, 'gi');
text = text.replace(sanitizeRegex, '');

// 5. 🏗 АВТО-БАЛАНСИРОВЩИК ТЕГОВ (Лечит ошибку Unmatched end tag)
const stack =[];
const tagRegex = /<\/?([a-z]+)[^>]*>/gi;
let match;

// Проходим по всем тегам в тексте
while ((match = tagRegex.exec(text)) !== null) {
  const tag = match[1].toLowerCase();
  const isClosing = match[0].startsWith('</');

  if (!isClosing) {
    // Если тег открылся - кладем его в "память"
    stack.push(tag);
  } else {
    // Если тег закрылся - убираем его из памяти
    const lastIndex = stack.lastIndexOf(tag);
    if (lastIndex !== -1) {
      stack.splice(lastIndex, 1); 
    }
  }
}

// Все теги, которые остались в "памяти" - нейросеть забыла закрыть!
// Аккуратно закрываем их в самом конце текста в обратном порядке
for (let i = stack.length - 1; i >= 0; i--) {
  text += `</${stack[i]}>`;
}

// 6. Убираем лишние пустые строки
text = text.replace(/\n{3,}/g, '\n\n');

return { 
  json: { 
    ...$json,
    output: text.trim() 
  } 
};

// Разбор JSON-конверта от агента. Записи (симптом/заметка/расследование/анализы) — НЕ
// инструменты агента, он кладёт их в JSON, n8n пишет нодами ниже. Здесь же — ремонт
// типовой поломки Gemini (незаэкранированная " внутри answer) и защита от «утёкшего» вызова.
let raw = String($json.output || '').trim();
raw = raw.replace(/^﻿/, '').replace(/^\s*[\x60]{3}(?:json)?\s*/i, '').replace(/\s*[\x60]{3}\s*$/, '').trim();

let env = null;
try { env = JSON.parse(raw); } catch (e) {}

// --- РЕМОНТ: конверт явно начат ("{ ... "answer": " ...), но JSON.parse упал ---
// Самая частая причина у gemini-3.8-flash: голая " внутри текста answer (напр. Прикрыть "дышащей" повязкой).
if ((!env || typeof env !== 'object' || Array.isArray(env)) && /^\s*\{[\s\S]{0,400}?"answer"\s*:\s*"/.test(raw)) {
  try {
    const keyIdx = raw.search(/"answer"\s*:/);
    const vs = raw.indexOf('"', raw.indexOf(':', keyIdx)) + 1;
    const endRe = /"\s*,\s*\r?\n?\s*"(?:awaiting_reply|log_symptom|medical_note|investigation|lab_plan)"\s*:/g;
    endRe.lastIndex = vs;
    const em = endRe.exec(raw);
    const ve = em ? em.index : raw.length;
    const inner = raw.slice(vs, ve);
    // раскодируем те экранизации, что модель ВСЁ ЖЕ поставила — получаем чистый текст
    const plain = inner
      .replace(/\r\n?/g, '\n')
      .replace(/\\r\\n?/g, '\n').replace(/\\n/g, '\n').replace(/\\t/g, '\t')
      .replace(/\\"/g, '"').replace(/\\\\/g, '\\')
      .trim();
    // пересобираем весь конверт с правильно закодированным answer
    const rebuilt = raw.slice(0, keyIdx) + '"answer": ' + JSON.stringify(plain) + (em ? raw.slice(em.index + 1) : '\n}');
    try { env = JSON.parse(rebuilt); } catch (e2) { env = null; }
    if (!env || typeof env !== 'object') env = { answer: plain };
    if (!env.answer) env.answer = plain;
    // добираем поля регэкспом, если пересборка их потеряла
    if (env.awaiting_reply === undefined) {
      const am = raw.match(/"awaiting_reply"\s*:\s*(true|false)/);
      if (am) env.awaiting_reply = am[1] === 'true';
    }
    for (const k of ['log_symptom', 'medical_note', 'investigation']) {
      if (env[k] === undefined) {
        const km = raw.match(new RegExp('"' + k + '"\\s*:\\s*(null|\\{[\\s\\S]*?\\n\\s*\\})'));
        if (km) { if (km[1] === 'null') env[k] = null; else { try { env[k] = JSON.parse(km[1]); } catch (e3) { env[k] = null; } } }
      }
    }
    if (env.lab_plan === undefined) {
      const pm = raw.match(/"lab_plan"\s*:\s*(null|\[[\s\S]*?\]\s*)/);
      if (pm) { if (pm[1].trim() === 'null') env.lab_plan = null; else { try { env.lab_plan = JSON.parse(pm[1]); } catch (e4) { env.lab_plan = null; } } }
    }
  } catch (eR) { /* ремонт не удался — уйдём в общий фолбэк ниже */ }
}

if (!env || typeof env !== 'object' || Array.isArray(env)) {
  // не JSON и не чинится. Утёкший tool-call → ошибка; нормальная проза → оборачиваем.
  const looksLikeLeak = /^\s*(Calling|Invoking|Использую|Вызываю|Вызов)\s+[A-Za-z_А-Яа-яЁё]/i.test(raw)
    || /\bwith\s+input\s*:\s*\{/i.test(raw)
    || /<\|?tool_call\|?>|functions\.[A-Za-z_]+\s*\(/i.test(raw)
    || (raw.startsWith('{') && !/"answer"\s*:/.test(raw) && /"(Symptom_ID|Note|Inv_ID|Plan_ID)"\s*:/.test(raw));
  if (raw && raw.length > 15 && !looksLikeLeak) {
    env = { answer: raw };
  } else {
    throw new Error('Агент не вернул валидный JSON-конверт с полем answer. Начало: ' + raw.slice(0, 160));
  }
}
if (!env.answer || typeof env.answer !== 'string' || env.answer.trim().length < 3) {
  throw new Error('В конверте агента нет поля answer. Ключи: ' + Object.keys(env).join(',') + ' | ' + raw.slice(0, 120));
}

const chat_id = (() => { try { return $('Главврач').first().json.message.chat.id; } catch (e) { return null; } })();
const dtHM = new Date(Date.now() + 10 * 3600e3).toISOString().slice(0, 16).replace('T', ' '); // yyyy-MM-dd HH:mm
const dISO = dtHM.slice(0, 10);
const dDot = dISO.replace(/-/g, '.');
const dtTs = new Date().toISOString(); // UTC для Postgres timestamptz

const awaiting = env.awaiting_reply === true || env.awaiting_reply === 'true';
const ls = (!awaiting && env.log_symptom && typeof env.log_symptom === 'object') ? env.log_symptom : null;
const mn = (!awaiting && env.medical_note) ? (typeof env.medical_note === 'string' ? { Note: env.medical_note } : env.medical_note) : null;
const iv = (!awaiting && env.investigation && typeof env.investigation === 'object') ? env.investigation : null;
const lp = (!awaiting && Array.isArray(env.lab_plan) && env.lab_plan.length) ? env.lab_plan : null;
const invAction = iv ? String(iv.action || 'open').toLowerCase() : '';

return [{
  json: {
    output: env.answer,
    chat_id,
    dt_hm: dtHM, dt_iso: dISO, dt_dot: dDot, dt_ts: dtTs,
    log_symptom: ls, medical_note: mn, investigation: iv, lab_plan: lp,
    has_symptom: !!ls, has_note: !!mn, has_inv: !!iv, has_lab: !!lp,
    inv_action: invAction,
    awaiting_reply: awaiting,
  },
}];
